CREATE TABLE roles (id BIGINT NOT NULL AUTO_INCREMENT, code VARCHAR(60) NOT NULL, name VARCHAR(120) NOT NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (id), UNIQUE KEY uk_roles_code (code)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE users (id BIGINT NOT NULL AUTO_INCREMENT, user_type VARCHAR(30) NOT NULL, name VARCHAR(150) NULL, email VARCHAR(180) NULL, mobile VARCHAR(20) NULL, password_hash VARCHAR(255) NOT NULL, account_status VARCHAR(40) NOT NULL, email_verified BOOLEAN NOT NULL DEFAULT FALSE, mobile_verified BOOLEAN NOT NULL DEFAULT FALSE, last_login_at TIMESTAMP(6) NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (id), UNIQUE KEY uk_users_email (email), UNIQUE KEY uk_users_mobile (mobile), KEY idx_users_email (email), KEY idx_users_mobile (mobile), KEY idx_users_status (account_status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE user_roles (id BIGINT NOT NULL AUTO_INCREMENT, user_id BIGINT NOT NULL, role_id BIGINT NOT NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (id), UNIQUE KEY uk_user_roles_user_role (user_id, role_id), KEY idx_user_roles_user (user_id), KEY idx_user_roles_role (role_id), CONSTRAINT fk_user_roles_user FOREIGN KEY (user_id) REFERENCES users(id), CONSTRAINT fk_user_roles_role FOREIGN KEY (role_id) REFERENCES roles(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE refresh_tokens (id BIGINT NOT NULL AUTO_INCREMENT, user_id BIGINT NOT NULL, token_hash VARCHAR(128) NOT NULL, status VARCHAR(30) NOT NULL, expires_at TIMESTAMP(6) NOT NULL, revoked_at TIMESTAMP(6) NULL, replaced_by_token_id BIGINT NULL, ip_address VARCHAR(80) NULL, user_agent VARCHAR(500) NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY (id), UNIQUE KEY uk_refresh_tokens_hash (token_hash), KEY idx_refresh_tokens_user (user_id), KEY idx_refresh_tokens_hash (token_hash), KEY idx_refresh_tokens_status (status), CONSTRAINT fk_refresh_tokens_user FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE login_attempts (id BIGINT NOT NULL AUTO_INCREMENT, user_id BIGINT NULL, email_or_mobile VARCHAR(180) NULL, attempt_type VARCHAR(40) NOT NULL, success BOOLEAN NOT NULL DEFAULT FALSE, attempted_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), ip_address VARCHAR(80) NULL, user_agent VARCHAR(500) NULL, PRIMARY KEY (id), KEY idx_login_attempts_user (user_id), KEY idx_login_attempts_identifier (email_or_mobile), KEY idx_login_attempts_time (attempted_at), CONSTRAINT fk_login_attempts_user FOREIGN KEY (user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE audit_logs (id BIGINT NOT NULL AUTO_INCREMENT, actor_user_id BIGINT NULL, actor_role VARCHAR(80) NULL, action_type VARCHAR(120) NOT NULL, entity_type VARCHAR(120) NOT NULL, entity_id VARCHAR(120) NULL, before_json JSON NULL, after_json JSON NULL, ip_address VARCHAR(80) NULL, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), PRIMARY KEY (id), KEY idx_audit_logs_actor (actor_user_id), KEY idx_audit_logs_entity (entity_type, entity_id), KEY idx_audit_logs_action_time (action_type, created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
INSERT INTO roles (code, name) VALUES ('CUSTOMER','Customer'),('ADMIN','Admin'),('SUPER_ADMIN','Super Admin');
